  function paint(previous: Reading, current: Reading) {
    drawRow(previous, 0); drawRow(current, 1);
    const pixels = context!.getImageData(0, 0, ATLAS_WIDTH, ATLAS_HEIGHT);
    // Reuse ImageData's backing buffer directly; no second 8 MiB pixel copy.
    atlas.image.data = new Uint8Array(pixels.data.buffer, pixels.data.byteOffset, pixels.data.byteLength);
    atlas.needsUpdate = true; atlasUpdates++;
