    bookSmoke.initialState=await bookState();const originalOrigin=bookSmoke.initialState.timeOrigin;
    let retained;
    await bookStep('desktop-open',async()=>{await page.locator('#open-book').click();await readyBook();});
    await bookStep('desktop-next-chapter',async()=>{
     const previous=(await bookState()).chapterTitle;await page.locator('#next').click();
     await page.waitForFunction(previous=>document.querySelector('#chapter-title')?.textContent!==previous,previous,{timeout:180000});
     await page.waitForFunction(()=>document.querySelector('#book')?.getAttribute('aria-busy')==='false',undefined,{timeout:180000});
     const state=await bookState();retained={title:state.chapterTitle,count:state.chapterCount};await bookPicture('desktop');
    });
    await bookStep('desktop-close',async()=>{await page.locator('#close-book').click();await readyRoom();});
    await bookStep('phone-resize-and-open',async()=>{
     await page.setViewportSize({width:390,height:844});await page.locator('#open-book').click();await readyBook();
     const state=await bookState();if(state.chapterTitle!==retained.title||state.chapterCount!==retained.count)throw new Error('Chapter changed during phone resize/reopen');
     await bookPicture('phone');
    });
    await bookStep('phone-close',async()=>{await page.locator('#close-book').click();await readyRoom();});
    await bookStep('phone-reopen-retains-chapter',async()=>{
     await page.locator('#open-book').click();await readyBook();const state=await bookState();
     if(state.chapterTitle!==retained.title||state.chapterCount!==retained.count)throw new Error('Chapter did not persist across phone close/reopen');
    });
    await bookStep('phone-final-close',async()=>{await page.locator('#close-book').click();await readyRoom();});
    bookSmoke.retained=retained;bookSmoke.finalState=await bookState();
    bookSmoke.graphicsAfter=await page.evaluate(()=>window.__visual2Perf.snapshot());
    if(bookSmoke.finalState.timeOrigin!==originalOrigin)throw new Error('The post-measurement book smoke unexpectedly reloaded the page');
    const finalMedia=bookSmoke.finalState.media;
    const naturalRecordEnd=!!finalMedia&&Number.isFinite(finalMedia.duration)&&finalMedia.duration>0&&finalMedia.ended===true&&finalMedia.paused===true
     &&finalMedia.currentTime>=finalMedia.duration-.1&&finalMedia.error===null&&bookSmoke.finalState.recordState==='已暂停';
    bookSmoke.recordPlayback={initial:bookSmoke.initialState.media,final:finalMedia,statusChanged:bookSmoke.finalState.recordState!==bookSmoke.initialState.recordState,naturalRecordEnd};
    if(bookSmoke.recordPlayback.statusChanged&&!naturalRecordEnd)throw new Error('Record playback status changed without a verified natural track end during book interactions');
    bookSmoke.errors=sample.errors.slice(countsAtStart.errors);bookSmoke.consoleErrors=sample.consoleErrors.slice(countsAtStart.consoleErrors);
    bookSmoke.warnings=sample.warnings.slice(countsAtStart.warnings);bookSmoke.failedRequests=sample.failedRequests.slice(countsAtStart.failedRequests);
    bookSmoke.httpErrors=sample.httpErrors.slice(countsAtStart.httpErrors);
    if(bookSmoke.errors.length||bookSmoke.consoleErrors.length||bookSmoke.failedRequests.length||bookSmoke.httpErrors.length)throw new Error('Browser error or failed request occurred during post-measurement book smoke');
    if(bookSmoke.warnings.some(item=>/GL_INVALID_VALUE|Offset overflows texture dimensions/i.test(item)))throw new Error('Texture allocation warning occurred during post-measurement book smoke');
    bookSmoke.passed=true;progress('book:passed',{steps:bookSmoke.steps.length,screenshots:bookSmoke.screenshots.length});
   }catch(error){
    bookSmoke.failure=String(error.stack??error);bookSmoke.failureState=await bookState().catch(()=>null);
    bookSmoke.errors=sample.errors.slice(countsAtStart.errors);bookSmoke.consoleErrors=sample.consoleErrors.slice(countsAtStart.consoleErrors);
    bookSmoke.warnings=sample.warnings.slice(countsAtStart.warnings);bookSmoke.failedRequests=sample.failedRequests.slice(countsAtStart.failedRequests);
    bookSmoke.httpErrors=sample.httpErrors.slice(countsAtStart.httpErrors);process.exitCode=1;
    progress('book:failed',{failure:bookSmoke.failure});
   }finally{bookSmoke.finishedAt=new Date().toISOString();await save();}
  }
 }catch(error){sample.failure=String(error.stack??error);sample.qualified=false;}
 finally{if(tracing&&cdp)await cdp.send('Tracing.end').catch(()=>{});await context?.close().catch(()=>{});await browser?.close().catch(()=>{});await save();console.log(JSON.stringify({stage:'finished',label,case:config.id,repeat,qualified:sample.qualified,frames:sample.drawnFrames,ms:sample.sampleWallMs,total:sample.timings?.totalMs,update:sample.timings?.updateMs,warnings:sample.qualificationWarnings,failure:sample.failure}));}
}
report.summary=selected.map(config=>{
 const all=report.samples.filter(s=>s.case===config.id),valid=all.filter(s=>s.qualified);
 return{case:config.id,total:all.length,qualified:valid.length,medianOfRunP50:{totalMs:percentile(valid.map(s=>s.timings.totalMs.p50),.5),updateMs:percentile(valid.map(s=>s.timings.updateMs.p50),.5),renderSubmitMs:percentile(valid.map(s=>s.timings.renderSubmitMs.p50),.5)},medianOfRunP95:{totalMs:percentile(valid.map(s=>s.timings.totalMs.p95),.5),updateMs:percentile(valid.map(s=>s.timings.updateMs.p95),.5),renderSubmitMs:percentile(valid.map(s=>s.timings.renderSubmitMs.p95),.5)}};
});
await save();console.log(JSON.stringify({output,summary:report.summary,samples:report.samples.length,qualified:report.samples.filter(s=>s.qualified).length}));
if(report.samples.some(s=>!s.qualified))process.exitCode=1;

