import { build } from 'esbuild';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { pathToFileURL, fileURLToPath } from 'node:url';
import { performance } from 'node:perf_hooks';
import assert from 'node:assert/strict';

const folder = dirname(fileURLToPath(import.meta.url)), root = resolve(folder, '../..');
const baseline = '5ded761e21a128eed27c29a32799349305aaadc5';
const relativeSource = 'src/pier-surf.ts', source = resolve(root, relativeSource);
const options = {};
for (const argument of process.argv.slice(2)) {
  if (argument === '--help') {
    console.log('node .work/frame-stall-20261119/pier-benchmark.mjs [--iterations=240] [--repeats=3] [--out=.work/frame-stall-20261119/pier-benchmark.json]');
    console.log('CPU-only exact-output comparison; bundles installed local dependencies, creates native Three.js objects without WebGL, alternates before/after order. No FPS, GPU or physical-device claim.');
    process.exit(0);
  }
  const match = /^--(iterations|repeats|out)=(.+)$/.exec(argument);
  if (!match) throw new Error(`Unknown option: ${argument}`);
  options[match[1]] = match[2];
}
const iterations = Number(options.iterations ?? 240), repeats = Number(options.repeats ?? 3);
if (!Number.isInteger(iterations) || iterations < 120 || !Number.isInteger(repeats) || repeats < 3)
  throw new Error('Use at least 120 updates and three repetitions.');
const output = resolve(root, options.out ?? '.work/frame-stall-20261119/pier-benchmark.json');
const sha = value => createHash('sha256').update(value).digest('hex');
const oldSource = execFileSync('git', ['show', `${baseline}:${relativeSource}`], { cwd: root, encoding: 'utf8' });
await mkdir(folder, { recursive: true });
await mkdir(dirname(output), { recursive: true });
const modules = {};
for (const variant of ['before', 'after']) {
  const path = resolve(folder, `pier-${variant}-cpu.mjs`);
  await build({ absWorkingDir: root, entryPoints: [source], outfile: path, bundle: true, platform: 'node',
    format: 'esm', target: 'node20', external: ['three'], logLevel: 'silent',
    plugins: variant === 'before' ? [{ name: 'frozen-pier-source', setup(plugin) {
      plugin.onLoad({ filter: /pier-surf\.ts$/ }, args => args.path === source ? { contents: oldSource, loader: 'ts' } : undefined);
    } }] : [],
  });
  modules[variant] = await import(pathToFileURL(path).href);
}

// The source's public sampler accepts these deterministic contacts; the CPU
// fixtures do not need to import another bundle of the navigation module.
const amounts = Array.from({ length: 12 }, (_, i) => .1 + .76 * i / 11);
const weather = { windSpeed: 18, windDirection: 2.2, waveScale: 1.5 };
const cases = [
  { name: 'slow-storm-full', step: 1.8, low: false, reduced: false, weather },
  { name: 'normal-storm-full', step: 1 / 60, low: false, reduced: false, weather },
  { name: 'slow-storm-low', step: 1.8, low: true, reduced: false, weather },
  { name: 'slow-calm-full', step: 1.8, low: false, reduced: false, weather: { windSpeed: 4, windDirection: .3, waveScale: .83 } },
];
const report = {
  schema: 1, measuredAt: new Date().toISOString(), baseline, node: process.version,
  sourceHashes: { before: sha(oldSource), after: sha(await readFile(source)) },
  method: { iterations, repeats, warmupUpdates: 120, freshSurfPerSample: true,
    order: 'Before/after order alternates by repetition; no browser or GPU workload is started by this helper.',
    timing: 'Native performance.now elapsed milliseconds and process.cpuUsage deltas; constructor, bundling and hashing are outside timing.',
    equivalence: 'All current geometry attribute/index buffers, both instance matrices, draw counts, uniforms and public snapshot hashed; resource budgets compared.',
    limits: ['Three.js constructors and update methods run in Node without WebGL.', 'Measures algorithmic CPU work, not browser renderSubmit/GPU stalls, physical device FPS, power or battery.', 'Three short repetitions are observations, not a statistical global no-regression conclusion.'],
  }, samples: [], summary: [],
};

function resources(surf) {
  const geometries = new Set(), materials = new Set(), textures = new Set(), lights = [];
  surf.group.traverse(object => {
    if (object.isLight) lights.push(object);
    if (object.geometry) geometries.add(object.geometry);
    if (object.material) for (const material of Array.isArray(object.material) ? object.material : [object.material]) {
      materials.add(material);
      for (const uniform of Object.values(material.uniforms ?? {})) if (uniform.value?.isTexture) textures.add(uniform.value);
    }
  });
  return { geometries: geometries.size, materials: materials.size, textures: textures.size, lights: lights.length };
}
function fingerprint(surf) {
  const hash = createHash('sha256');
  const add = array => hash.update(Buffer.from(array.buffer, array.byteOffset, array.byteLength));
  surf.group.traverse(object => {
    hash.update(object.name);
    if (object.geometry) {
      for (const name of Object.keys(object.geometry.attributes).sort()) { hash.update(name); add(object.geometry.attributes[name].array); }
      if (object.geometry.index) add(object.geometry.index.array);
      hash.update(JSON.stringify(object.geometry.drawRange));
    }
    if (object.instanceMatrix) add(object.instanceMatrix.array);
    if (object.count !== undefined) hash.update(String(object.count));
    if (object.material?.uniforms) hash.update(JSON.stringify(Object.fromEntries(Object.entries(object.material.uniforms).map(([key, value]) => [key, value.value]))));
  });
  hash.update(JSON.stringify(surf.snapshot()));
  return hash.digest('hex');
}
function measureUpdate(variant, config, repeat) {
  const surf = modules[variant].createPierSurf(), startTime = 1000 + repeat * 37.3;
  try {
    for (let i = 0; i < 120; i++) surf.update(startTime + i * config.step, config.weather, config.low, config.reduced);
    const style = surf.group.getObjectByName('pier-curling-wave-sheets').geometry.attributes.surfStyle;
    const styleVersion = style.version, cpu = process.cpuUsage(), started = performance.now();
    for (let i = 0; i < iterations; i++) surf.update(startTime + (i + 120) * config.step, config.weather, config.low, config.reduced);
    const elapsedMs = performance.now() - started, cpuMicroseconds = process.cpuUsage(cpu);
    return { variant, case: config.name, repeat, updates: iterations, elapsedMs, perUpdateMs: elapsedMs / iterations,
      cpuMicroseconds, resourceBudget: resources(surf), hash: fingerprint(surf), styleUploadNotifications: style.version - styleVersion };
  } finally { surf.dispose(); }
}
function measureQueries(variant, repeat) {
  const sampler = modules[variant].samplePierImpact, results = new Array(iterations * amounts.length * 2);
  const baseTime = 1000 + repeat * 37.3;
  for (let i = 0; i < 120; i++) sampler(amounts[i % amounts.length], i % 2 ? 1 : -1, baseTime + i * 1.8, weather);
  const cpu = process.cpuUsage(), started = performance.now(); let next = 0;
  for (let i = 0; i < iterations; i++) for (const side of [1, -1]) for (const amount of amounts)
    results[next++] = sampler(amount, side, baseTime + i * 1.8, weather);
  const elapsedMs = performance.now() - started, cpuMicroseconds = process.cpuUsage(cpu);
  return { variant, case: 'public-absolute-24-contacts', repeat, queries: results.length, elapsedMs,
    perQueryMs: elapsedMs / results.length, cpuMicroseconds, hash: sha(JSON.stringify(results)) };
}
const expectedResources = { geometries: 3, materials: 3, textures: 0, lights: 0 };
for (let repeat = 1; repeat <= repeats; repeat++) {
  const order = repeat % 2 ? ['before', 'after'] : ['after', 'before'];
  for (const config of cases) {
    const pair = order.map(variant => measureUpdate(variant, config, repeat));
    for (const sample of pair) assert.deepEqual(sample.resourceBudget, expectedResources);
    assert.equal(pair[0].hash, pair[1].hash, `Different full buffer/snapshot output in ${config.name}, repetition ${repeat}`);
    report.samples.push(...pair);
    console.log(JSON.stringify({ case: config.name, repeat, samples: pair.map(({ variant, elapsedMs, styleUploadNotifications }) => ({ variant, elapsedMs, styleUploadNotifications })), exactHash: pair[0].hash }));
  }
  const pair = order.map(variant => measureQueries(variant, repeat));
  assert.equal(pair[0].hash, pair[1].hash, `Different query results in repetition ${repeat}`);
  report.samples.push(...pair);
  console.log(JSON.stringify({ case: pair[0].case, repeat, samples: pair.map(({ variant, elapsedMs }) => ({ variant, elapsedMs })), exactHash: pair[0].hash }));
}
const median = values => [...values].sort((a, b) => a - b)[Math.floor(values.length / 2)];
for (const name of [...cases.map(config => config.name), 'public-absolute-24-contacts']) {
  const before = report.samples.filter(sample => sample.case === name && sample.variant === 'before');
  const after = report.samples.filter(sample => sample.case === name && sample.variant === 'after');
  const beforeMedianMs = median(before.map(sample => sample.elapsedMs)), afterMedianMs = median(after.map(sample => sample.elapsedMs));
  report.summary.push({ case: name, repetitions: repeats, beforeMedianMs, afterMedianMs,
    afterOverBefore: afterMedianMs / beforeMedianMs, observedElapsedReductionPercent: (1 - afterMedianMs / beforeMedianMs) * 100,
    exactOutputHashesMatch: before.every(sample => after.find(other => other.repeat === sample.repeat).hash === sample.hash) });
}
report.completedAt = new Date().toISOString();
await writeFile(output, JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify({ output, summary: report.summary }));
